```
inline void simplify(std::vector<vt_point>& points, double tolerance) {
    const size_t len = points.size();

    // always retain the endpoints (1 is the max value)
    points[0].z = 1.0;
    points[len - 1].z = 1.0;

    simplify(points, 0, len - 1, tolerance * tolerance);
}
